"""Row-limit boundary: independent completion-set counting vs driver images."""
import itertools, sys
sys.path.insert(0, '/workspace/tests')
from harness import *

SVC = [{"name": "A", "label": 1}, {"name": "B", "label": 2}]
LIM = {"images": 16, "cells": 262144, "units": 1024, "contexts": 32768,
       "connections": 4096, "packets": 32768, "files": 8192}

def count_rows(wordset):
    """Row count of the minimal complete DFA minus dead residual.

    Residual(u) = set of completions of u in the word set.  Two nodes share a
    residual iff their canonical completion structures are equal.
    """
    words = set(tuple(w) for w in wordset)
    if not words:
        return 1
    children = [{}]
    terminal = [False]
    for w in words:
        node = 0
        for ch in w:
            nxt = children[node].get(ch)
            if nxt is None:
                nxt = len(children)
                children[node][ch] = nxt
                children.append({})
                terminal.append(False)
            node = nxt
        terminal[node] = True
    canon = [None] * len(children)

    def canon_of(node):
        if canon[node] is None:
            entries = frozenset((ch, canon_of(ch2)) for ch, ch2 in children[node].items())
            canon[node] = (terminal[node], entries)
        return canon[node]

    uniq = {canon_of(n) for n in range(len(children))}
    return len(uniq)

def make_policy(wordset):
    return "".join(f"match({','.join(w)}) allow;" for w in sorted(wordset))

def rows_from_driver(wordset):
    r = run_cli(req([job(SVC, [{"op": "stage", "epoch": 1, "policy": make_policy(wordset)}], LIM)]))
    e = r["results"][0]["events"][0]
    return len(e['image']['rows']) if 'image' in e else e

def expect_rows(name, wordset):
    n = count_rows(wordset)
    want = n if n <= 8192 else {"error": "rejected"}
    got = rows_from_driver(wordset)
    if n > 8192:
        check(name + f" (rows {n} > 8192)", got, {"error": "rejected"})
    elif isinstance(got, int):
        check(name + f" (rows {n})", got, want)
    else:
        check(name + f" (rows {n})", got, want)

# chain words A^i B (paths capped at 16 services)
for n in (2, 5, 16):
    expect_rows(f"chain n={n}", [("A",)*i + ("B",) for i in range(n)])

# binary words of length 12 minus k deletions
full = list(itertools.product("AB", repeat=12))
for k in (0, 1, 10, 700):
    expect_rows(f"binary12 minus {k}", full[:-k] if k else full)

# locate exact boundary 8192 / 8193 and check both sides
found = {}
for k in range(500, 1200):
    n = count_rows(full[:-k])
    if n in (8192, 8193) and n not in found:
        found[n] = k
print("   boundary k for rows:", found)
for n, k in sorted(found.items()):
    expect_rows(f"boundary rows={n} k={k}", full[:-k])
if 8192 not in found or 8193 not in found:
    print("[WARN] could not hit exact boundary; ran available samples")

summary()
EOF
